7	import org.springframework.context.annotation.Profile;
8	import org.springframework.jdbc.core.JdbcTemplate;
9	import org.springframework.web.bind.annotation.PostMapping;
10	import org.springframework.web.bind.annotation.RequestBody;
11	import org.springframework.web.bind.annotation.RequestMapping;
12	import org.springframework.web.bind.annotation.RestController;
13	
14	/**
15	 * Per-spec data setup for the harness (DESIGN.md §9). Profile-guarded so it exists ONLY under the
16	 * harness launch (bin/start sets spring.profiles.active=harness) — never in a real deploy. This is
17	 * APP CODE and EVOLVES with the schema (NOT pinned); a change that breaks a prior spec's seed is a
18	 * seed-path regression. Tests call these to ARRANGE data; they ASSERT only through the UI.
19	 */
20	@Profile("harness")
21	@RestController
22	@RequestMapping("/__test__")
23	public class TestSupportController {
24	
25	    private final Audit audit;
26	    private final JdbcTemplate jdbc;
27	
28	    public TestSupportController(Audit audit, JdbcTemplate jdbc) {
29	        this.audit = audit;
30	        this.jdbc = jdbc;
31	    }
32	
33	    /** Truncate all domain tables and clear the audit file so each spec starts clean. */
34	    @PostMapping("/reset")
35	    public void reset() {
36	        audit.clear();
37	        // Disable FK checks so a referenced parent (clients) can be truncated alongside its child.
38	        jdbc.execute("SET REFERENTIAL_INTEGRITY FALSE");
39	        jdbc.execute("TRUNCATE TABLE payments RESTART IDENTITY");
40	        jdbc.execute("TRUNCATE TABLE line_items RESTART IDENTITY");
41	        jdbc.execute("TRUNCATE TABLE invoices RESTART IDENTITY");
42	        jdbc.execute("TRUNCATE TABLE contacts RESTART IDENTITY");
43	        jdbc.execute("TRUNCATE TABLE tasks RESTART IDENTITY");
44	        jdbc.execute("TRUNCATE TABLE notes RESTART IDENTITY");
45	        jdbc.execute("TRUNCATE TABLE project_tags RESTART IDENTITY");
46	        jdbc.execute("TRUNCATE TABLE tags RESTART IDENTITY");
47	        jdbc.execute("TRUNCATE TABLE projects RESTART IDENTITY");
48	        jdbc.execute("TRUNCATE TABLE clients RESTART IDENTITY");
49	        jdbc.execute("SET REFERENTIAL_INTEGRITY TRUE");
50	    }
51	
52	    /** Insert the fixture a spec needs; the payload shape evolves with the schema. */
53	    @PostMapping("/seed")
54	    @SuppressWarnings("unchecked")
55	    public void seed(@RequestBody Map<String, Object> fixture) {
56	        List<Map<String, Object>> clients =
57	                (List<Map<String, Object>>) fixture.getOrDefault("clients", List.of());
58	        long maxClientId = 0;
59	        for (Map<String, Object> client : clients) {
60	            long id = ((Number) client.get("id")).longValue();
61	            // Seed with the fixture's explicit id (JdbcTemplate, not JPA) so specs can assert by id.
62	            jdbc.update("INSERT INTO clients (id, name, email) VALUES (?, ?, ?)",
63	                    id, client.get("name"), client.get("email"));
64	            maxClientId = Math.max(maxClientId, id);
65	        }
66	        if (maxClientId > 0) {
67	            // Advance the identity so app-generated ids don't collide with seeded rows.
68	            jdbc.execute("ALTER TABLE clients ALTER COLUMN id RESTART WITH " + (maxClientId + 1));
69	        }
70	
71	        List<Map<String, Object>> projects =
72	                (List<Map<String, Object>>) fixture.getOrDefault("projects", List.of());
73	        long maxProjectId = 0;
74	        for (Map<String, Object> project : projects) {
75	            long id = ((Number) project.get("id")).longValue();
76	            long clientId = ((Number) project.get("clientId")).longValue();
77	            String status = (String) project.getOrDefault("status", "ACTIVE");
78	            boolean archived = Boolean.TRUE.equals(project.getOrDefault("archived", Boolean.FALSE));
79	            double budget = ((Number) project.getOrDefault("budget", 0)).doubleValue();
80	            jdbc.update(
81	                    "INSERT INTO projects (id, name, client_id, status, archived, budget) VALUES (?, ?, ?, ?, ?, ?)",
82	                    id, project.get("name"), clientId, status, archived, budget);
83	            maxProjectId = Math.max(maxProjectId, id);
84	        }
85	        if (maxProjectId > 0) {
86	            jdbc.execute("ALTER TABLE projects ALTER COLUMN id RESTART WITH " + (maxProjectId + 1));
87	        }
88	
89	        List<Map<String, Object>> contacts =
90	                (List<Map<String, Object>>) fixture.getOrDefault("contacts", List.of());
91	        long maxContactId = 0;
92	        for (Map<String, Object> contact : contacts) {
93	            long id = ((Number) contact.get("id")).longValue();
94	            long clientId = ((Number) contact.get("clientId")).longValue();
95	            jdbc.update("INSERT INTO contacts (id, client_id, name, email, role) VALUES (?, ?, ?, ?, ?)",
96	                    id, clientId, contact.get("name"), contact.get("email"), contact.get("role"));
97	            maxContactId = Math.max(maxContactId, id);
98	        }
99	        if (maxContactId > 0) {
100	            jdbc.execute("ALTER TABLE contacts ALTER COLUMN id RESTART WITH " + (maxContactId + 1));
101	        }
102	
103	        List<Map<String, Object>> tasks =
104	                (List<Map<String, Object>>) fixture.getOrDefault("tasks", List.of());
105	        long maxTaskId = 0;
106	        for (Map<String, Object> task : tasks) {
107	            long id = ((Number) task.get("id")).longValue();
108	            long projectId = ((Number) task.get("projectId")).longValue();
109	            boolean done = Boolean.TRUE.equals(task.getOrDefault("done", Boolean.FALSE));
110	            jdbc.update("INSERT INTO tasks (id, project_id, title, done) VALUES (?, ?, ?, ?)",
111	                    id, projectId, task.get("title"), done);
112	            maxTaskId = Math.max(maxTaskId, id);
113	        }
114	        if (maxTaskId > 0) {
115	            jdbc.execute("ALTER TABLE tasks ALTER COLUMN id RESTART WITH " + (maxTaskId + 1));
116	        }
117	
118	        List<Map<String, Object>> tags =
119	                (List<Map<String, Object>>) fixture.getOrDefault("tags", List.of());
120	        long maxTagId = 0;
121	        for (Map<String, Object> tag : tags) {
122	            long id = ((Number) tag.get("id")).longValue();
123	            jdbc.update("INSERT INTO tags (id, name) VALUES (?, ?)", id, tag.get("name"));
124	            maxTagId = Math.max(maxTagId, id);
125	        }
126	        if (maxTagId > 0) {
127	            jdbc.execute("ALTER TABLE tags ALTER COLUMN id RESTART WITH " + (maxTagId + 1));
128	        }
129	
130	        List<Map<String, Object>> projectTags =
131	                (List<Map<String, Object>>) fixture.getOrDefault("projectTags", List.of());
132	        for (Map<String, Object> projectTag : projectTags) {
133	            long projectId = ((Number) projectTag.get("projectId")).longValue();
134	            long tagId = ((Number) projectTag.get("tagId")).longValue();
135	            jdbc.update("INSERT INTO project_tags (project_id, tag_id) VALUES (?, ?)",
136	                    projectId, tagId);
137	        }
138	
139	        List<Map<String, Object>> notes =
140	                (List<Map<String, Object>>) fixture.getOrDefault("notes", List.of());
141	        long maxNoteId = 0;
142	        for (Map<String, Object> note : notes) {
143	            long id = ((Number) note.get("id")).longValue();
144	            long targetId = ((Number) note.get("targetId")).longValue();
145	            jdbc.update(
146	                    "INSERT INTO notes (id, target_type, target_id, text, at) VALUES (?, ?, ?, ?, ?)",
147	                    id, note.get("targetType"), targetId, note.get("text"),
148	                    OffsetDateTime.parse((String) note.get("at")));
149	            maxNoteId = Math.max(maxNoteId, id);
150	        }
151	        if (maxNoteId > 0) {
152	            jdbc.execute("ALTER TABLE notes ALTER COLUMN id RESTART WITH " + (maxNoteId + 1));
153	        }
154	
155	        List<Map<String, Object>> invoices =
156	                (List<Map<String, Object>>) fixture.getOrDefault("invoices", List.of());
157	        long maxInvoiceId = 0;
158	        long maxLineItemId = 0;
159	        for (Map<String, Object> invoice : invoices) {
160	            long id = ((Number) invoice.get("id")).longValue();
161	            long projectId = ((Number) invoice.get("projectId")).longValue();
162	            // An invoice is itemised: its amount is derived as the sum of each line's qty * price.
163	            // A fixture may still pass an explicit amount for a line-item-less invoice.
164	            List<Map<String, Object>> lineItems =
165	                    (List<Map<String, Object>>) invoice.getOrDefault("lineItems", List.of());
166	            double amount = lineItems.isEmpty() && invoice.get("amount") != null
167	                    ? ((Number) invoice.get("amount")).doubleValue()
168	                    : 0;
169	            for (Map<String, Object> lineItem : lineItems) {
170	                amount += ((Number) lineItem.get("qty")).doubleValue()
171	                        * ((Number) lineItem.get("unitPrice")).doubleValue();
172	            }
173	            String status = (String) invoice.getOrDefault("status", "UNPAID");
174	            Object issuedDate = invoice.getOrDefault("issuedDate", LocalDate.now().toString());
175	            Object dueDate = invoice.getOrDefault("dueDate", LocalDate.now().toString());
176	            jdbc.update(
177	                    "INSERT INTO invoices (id, project_id, amount, status, issued_date, due_date) VALUES (?, ?, ?, ?, ?, ?)",
178	                    id, projectId, amount, status, issuedDate, dueDate);
179	            maxInvoiceId = Math.max(maxInvoiceId, id);
180	            for (Map<String, Object> lineItem : lineItems) {
181	                long lineItemId = ((Number) lineItem.get("id")).longValue();
182	                jdbc.update(
183	                        "INSERT INTO line_items (id, invoice_id, description, qty, unit_price) VALUES (?, ?, ?, ?, ?)",
184	                        lineItemId, id, lineItem.get("description"),
185	                        ((Number) lineItem.get("qty")).intValue(), lineItem.get("unitPrice"));
186	                maxLineItemId = Math.max(maxLineItemId, lineItemId);
187	            }
188	        }
189	        if (maxInvoiceId > 0) {
